\label{thm:canonical}
\statusS/\statusA\;
Let $X_\Phi=(\Om,\tau_\Phi)$ be a finite ProLT. Then:
\begin{enumerate}[label=(\roman*)]
\item the Kolmogorov quotient map $X_\Phi\to P_\Phi$ is a homotopy equivalence of finite Alexandrov spaces;
\item the geometric realization $|\OX_\Phi|\to P_\Phi$ supplied by McCord's finite-space construction is a weak homotopy equivalence;
\item for every coefficient ring $R$,
\[
H_k(X_\Phi;R)\cong H_k(P_\Phi;R)\cong H_k(\OX_\Phi;R).
\]
\end{enumerate}

\label{prop:premise}
\statusA\;
If $S'\subseteq S\subseteq\Om$, then
\[
P_{\Phi,S'}\subseteq P_{\Phi,S}
\]
and therefore
\[
\OX_{\Phi,S'}\subseteq\OX_{\Phi,S}
\]
as a full subcomplex on the surviving realized signatures.

\label{thm:tautology}
\statusA\;
Let $\Psi$ be obtained from $\Phi$ by adjoining one tautological observation $\top$.
Then:
\begin{enumerate}[label=(\roman*)]
\item $X_\Psi$ and $X_\Phi$ have the same topology;
\item $P_\Psi$ and $P_\Phi$ are order-isomorphic by $s\mapsto s\cup\{\top\}$, so $\OX_\Psi\cong\OX_\Phi$;
\item the new coordinate is equal at every state, so the symmetric and directed signature distances are unchanged;
\item $\K_\Psi$ is a cone with apex $\top$, hence $\widetilde H_k(\K_\Psi;R)=0$ for every $k$.
\end{enumerate}

\label{prop:SR}
\statusS/\statusA\;
The minimal squarefree monomial generators of $I_\Phi$ are in bijection with inclusion-minimal jointly unsatisfiable indexed subfamilies of $\Phi$.

\label{cor:possibleforced}
\statusA/\statusC\;
For a one-observation refinement:
\begin{enumerate}[label=(\roman*)]
\item \(r\) has a right adjoint if and only if \(M_\psi:P_\Phi\to\{0,1\}\) is isotone.
\item \(r\) has a left adjoint if and only if \(m_\psi:P_\Phi\to\{0,1\}\) is isotone.
\end{enumerate}
Equivalently, either of the following is sufficient for homotopy invariance:
\begin{itemize}
\item the coarse states in which \(\psi\) is \emph{possible} form an upset;
\item the coarse states in which \(\psi\) is \emph{forced} form an upset.
\end{itemize}
Topological redundancy is the stronger special case
\[
m_\psi=M_\psi=b
\]
with \(b\) isotone.

\label{thm:coneexact}
\statusS/\statusA/\statusC\;
The following are equivalent:
\begin{enumerate}[label=(\roman*)]
\item \(r_*:H_k(\OX_\Psi;R)\to H_k(\OX_\Phi;R)\) is an isomorphism for every \(k\);
\item
\[
D_k(\Psi/\Phi;R)=0
\qquad\text{for every }k.
\]
\end{enumerate}
Thus the refinement cone gives an exact, finite homological classification of whether the refinement is homology-neutral.

If any of the following differs between \(\OX_\Psi\) and \(\OX_\Phi\), the refinement is not homology-neutral:
\begin{enumerate}[label=(\alph*)]
\item a Betti number over the chosen field;
\item the number of connected components;
\item the Euler characteristic.
\end{enumerate}
The converses are false in general.

\label{thm:floorceil}
\statusS/\statusA/\statusC\;
If $\psi$ has either the false-floor property or the true-ceiling property, then adding $\psi$ preserves the homotopy type of the canonical ProLT order complex.

\label{cor:anchor}
\statusA/\statusC\;
Suppose every connected component $C$ of $P$ satisfies at least one of the following:
\begin{enumerate}[label=(\roman*)]
\item $C$ has a least element $\bot_C$ with $b(\bot_C)=0$;
\item $C$ has a greatest element $\top_C$ with $b(\top_C)=1$.
\end{enumerate}
Then refinement by $\psi$ preserves homotopy type.

\label{prop:incidence}
\statusS/\statusA/\statusC\;
Over $\F$, the relative boundary matrix
\[
\partial_2^{\rm rel}
\]
is exactly the vertex-edge incidence matrix of $\mathfrak R_\psi(P)$ after deleting the rows corresponding to the formal roots.

\label{thm:repairforest}
\statusS/\statusA/\statusC\;
Assume $P$ is post-$T_0$ and $\operatorname{ht}(P)\le2$. For one added observation $\psi$, the following are equivalent:
\begin{enumerate}[label=(\roman*)]
\item the inclusion $L_b\hookrightarrow K$ is a homotopy equivalence;
\item it is a simple homotopy equivalence;
\item $K$ simplicially collapses onto $L_b$ using only deleted edge--triangle pairs;
\item it is a homology equivalence over $\F$;
\item $\partial_2^{\rm rel}$ is invertible;
\item the rooted repair graph $\mathfrak R_\psi(P)$ is a forest in which every connected component contains exactly one formal root.
\end{enumerate}
Thus, in height two for one new observation,
\[
\boxed{\text{homology-neutral}\iff\text{homotopy-neutral}\iff\text{repair forest}.}
\]

\label{cor:greedy}
At height two, the following algorithm decides whether one added observation preserves homotopy:
\begin{enumerate}[label=\arabic*.]
\item list every descent edge $p<q$ with $b(p)=1,b(q)=0$;
\item list every deleted three-chain $x<y<z$;
\item repeatedly choose a currently deleted edge contained in exactly one currently deleted triangle and remove that edge--triangle pair;
\item succeed if all deleted cells are exhausted; fail otherwise.
\end{enumerate}
The algorithm succeeds if and only if the refinement preserves homotopy.

\label{prop:sequential}
\statusA\;
Every sequentially homotopy-safe block is jointly homotopy-neutral.

\statusS/\statusA\;
The decision problem
\[
\text{``is }\odim_P(Q)\le k\text{?''}
\]
is NP-complete already when $P$ is supplied as a total order extending $Q$.

\label{thm:coeff}
\statusS/\statusA\;
Suppose $|E_{\rm del}|=|T_{\rm del}|=m$. Then:
\begin{enumerate}[label=(\roman*)]
\item over a field $\Bbbk$, $L\hookrightarrow K$ is a homology equivalence iff $\det(B_{\mathbb Z})$ is nonzero in $\Bbbk$;
\item over $\mathbb Q$, this is equivalent to $\det(B_{\mathbb Z})\ne0$;
\item over $\mathbb Z$, the relative homology vanishes iff $\det(B_{\mathbb Z})=\pm1$;
\item if $d:=\det(B_{\mathbb Z})\ne0$, then
\[
H_2(K,L;\mathbb Z)=0,
\qquad
|H_1(K,L;\mathbb Z)|=|d|;
\]
\item for a prime $p$, relative homology over $\mathbb F_p$ is nonzero exactly when $p\mid d$.
\end{enumerate}
If the two deleted-cell counts differ, relative homology cannot vanish over any field.

\label{cor:unique}
\statusA\;
If the deleted-cell incidence graph has a unique perfect matching, then the block is Morse-safe and therefore homotopy-preserving.

\label{thm:failure}
\statusA/\statusC\;
For simultaneous height-two refinement, homotopy-neutrality does not imply the existence of an acyclic fitting orientation on the deleted edge--triangle pair. Consequently the v0.4 equivalence
\[
\text{homotopy-neutral}\iff\text{repair collapse}
\]
is special to the one-bit height-two regime.
